def exercise(ident, title, key, intro, prompt, choices, prefix=(), objective=None):
    start = P[key]
    quiz = after(prefix, start) if prefix else start
    frames = [step(start, intro)]
    if not prefix:
        frames.append(step(quiz, 'Calculation checkpoint: identify both kings, the active pieces and the opponent’s immediate threat before choosing your move.'))
    if prefix:
        frames.append(step(quiz, 'Calculation checkpoint: identify the threat and calculate the opponent’s strongest reply before moving.'))
    return lesson(5, 'ch5-' + ident, title, intro, frames, prompt, choices, objective=objective)


